[78701] = {id=78701,name="The Truth in Chalk",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="So the people of Taelloch use chalk on slate to leave messages to each other. So many clues! But what does it all mean.... I'm seeing a pattern, and I think it points to the mines. If the workers haven't already been lost, I'd expect them to be in the mines. And I know the foreman is the key. She has to be.",questType="world",worldTaskTitle="The Truth in Chalk"},
[78703] = {id=78703,name="Buried in Stone",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="We need to go into the cave, the one mentioned near the last slate. It's not signed, but I think that's the foreman's handwriting... and we've looked everywhere else. We have to investigate.",questType="world",worldTaskTitle="Buried in Stone"},
[78704] = {id=78704,name="Find the Foreman",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Dagran was right. I suppose I shouldn't be surprised by that any longer. All the signs suggest there's something in this cave. Maybe the foreman is hiding here. Maybe she can give us some answers. We've come this far. Let's see what's inside.",questType="world",worldTaskTitle="Find the Foreman"},
