[79167] = {id=79167,name="Crowdsourcing",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Light's Gambit is an old and honored game. There's a reason so many Arathi play it! It can teach you a lot about strategy. And it can tell you a lot about your opponents. But we're still missing a few pieces that we need in order to play. Sometimes, folks around Mereldar lend us pieces for a game. Could you ask around?",starts={{npcID=215331,x=0.406,y=0.708,mapID=2215}},ends={{npcID=218267,x=0.432,y=0.524,mapID=2215}},coords={x=0.406,y=0.708,source="quest_giver",mapID=2215},questType="world",worldTaskTitle="Crowdsourcing"},
[79168] = {id=79168,name="Light's Gambit",expansion=10,mapID=2215,questType="world",worldTaskTitle="Light's Gambit"},
[79200] = {id=79200,name="Who am I?",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="It's good to see you're awake. I know you must have many questions and we are here to answer them. I am Dawn , and this is Foreman Uzjax. Many things have changed since your last slumber began, including our Awakening Protocol. We are both here to guide you through it. Like many other newly awakened, you have heard a distant yet powerful song thrumming within you. A radiant surge of change. Embrace it.",questType="world",worldTaskTitle="Who am I?"},
[79201] = {id=79201,name="The Analysis Interface",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="This is the Analysis Interface. In order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. Although Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully. Proceed when ready.",questType="world",worldTaskTitle="The Analysis Interface"},
[79202] = {id=79202,name="Rock Beats Rock",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="Welcome to the Procedural Forum. Foreman Uzjax informs me that this chamber once served as our assignment testing facility. With his guidance, we've repurposed this chamber. Earthen are not combat trained by design, so this room serves to prepare newly awakened earthen for the challenges of the unexplored world that lies ahead.",questType="world",worldTaskTitle="Rock Beats Rock"},
[79203] = {id=79203,name="Authorization: Negated",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="The Bulwark of Authorization! That's what this chamber was once called. I had been working tirelessly to reconfigure it to its original state, when suddenly the whole blasted chamber started rumbling. A golem manifested out of nowhere and started attacking my machinists! We managed to escape, but the Golem locked down the chambers. Dawn seems to think you've got what it takes to deal with it. Up to the challenge?",questType="world",worldTaskTitle="Authorization: Negated"},
[79204] = {id=79204,name="Whoever You Want to Be",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="After an awakening protocol like that, I can see why Dawn says you're special. The world is not prepared for an earthen like you. Dawn and the Foreman are waiting for you in the Awakening Vestibule. Go on, then! Complete your Awakening Protocol and get out of here!",questType="world",worldTaskTitle="Whoever You Want to Be"},
