[83286] = {id=83286,name="What's Hidden Beneath Dornogal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13390,mapID=2367,description="Strange. The mechanism and console here is receiving power, but I cannot initialize the reboot sequence. Dagran's query may have to wait. I have been able to ascertain the facility's designation: the \"Vault of Memory.\" This leads me to believe that my original theory was correct. It is connected to the Archive in Dornogal. Perhaps, since both of you are familiar with this type of titan installation, you may have a better chance bringing it fully online.",starts={{npcID=226040,x=0.5,y=0.598,zoneID=13390}},ends={{npcID=226040,x=0.5,y=0.598,zoneID=13390}},coords={x=0.5,y=0.598,source="quest_giver",zoneID=13390},questType="world",worldTaskTitle="What's Hidden Beneath Dornogal"},
