[83328] = {id=83328,name="The Analysis Interface",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="This is the Analysis Interface. In order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. Although Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully. Proceed when ready.",questType="world",worldTaskTitle="The Analysis Interface"},
