[83723] = {id=83723,name="A Helping Hand",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Kalecgos's hypothesis that Dalaran's debris interferes with long-range teleportation seems correct. Mage portals have appeared along the shore, but no one has stepped through them. There are likely mages trapped within the portals. Or, something mana hungry--like felhunters--may be being lured here by the release of Dalaran's power. We must investigate. Mages of the Kirin Tor may be in danger. The felhunters are an acceptable risk. Let us not waste any more time.",starts={{npcID=212829,x=0.31,y=0.578,mapID=2248}},ends={{npcID=227409,x=0.298,y=0.578,mapID=2248}},coords={x=0.31,y=0.578,source="quest_giver",mapID=2248},questType="world",worldTaskTitle="A Helping Hand"},
