[87345] = {id=87345,name="Warrant: Xy'vox the Twisted",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Xy'vox the Twisted the former constable of Tazavesh, hailed from a powerful cartel family. Unknown to most, the family's power was obtained from illegal crimes, all conveniently overlooked by Xy'vox. When the truth came out, Xy'vox went into hiding. I believe the constable never left town, instead hides here in plain sight, continuing criminal activities. Create a Refuge Dampener to reveal Xy'vox to all of Tazavesh.",questType="world",worldTaskTitle="Warrant: Xy'vox the Twisted"},
